#include "LoRaWan_APP.h"
#include "Arduino.h"
#include "HT_SSD1306Wire.h"
#include <WiFi.h>
#include <WebServer.h>
#include <Preferences.h>
#include <esp_bt.h>
#include "esp_sleep.h"
#include <ArduinoOTA.h>

static SSD1306Wire display(0x3C, 500000, SDA_OLED, SCL_OLED, GEOMETRY_128_64, RST_OLED);

#define MIN_FREQ_MHZ 863.000
#define MAX_FREQ_MHZ 870.000
#define DEFAULT_RF_FREQUENCY 868000000UL

#define LORA_BANDWIDTH 0
#define LORA_SPREADING 7
#define LORA_CODINGRATE 1
#define LORA_PREAMBLE_LEN 8
#define LORA_SYMBOL_TIMEOUT 0
#define LORA_FIX_LEN false
#define LORA_IQ_INVERT false

uint32_t RF_FREQUENCY = DEFAULT_RF_FREQUENCY;

#define RSSI_MIN -135
#define RSSI_MAX -30

#define AUDIO_PIN 2
#define CW_TONE_FREQ 1000
#define CW_ON_THRESHOLD -108
#define CW_OFF_THRESHOLD -112

static RadioEvents_t RadioEvents;
bool rxActive = false;

#define PRG_BUTTON 0

#define CONFIG_HOLD_MS 1200

const char* AP_SSID = "M9WHQ-CW-RX-Config";
const char* AP_PASS = "foxhunt70";

WebServer server(80);
Preferences prefs;
bool configMode = false;
String restoreUploadJson = "";
bool isConfigModeActive = false;

void VextON() {
  pinMode(Vext, OUTPUT);
  digitalWrite(Vext, LOW);
}

String formatFrequencyMHz(uint32_t hz) {
  char buf[16];
  snprintf(buf, sizeof(buf), "%.3f", hz / 1000000.0);
  return String(buf);
}

uint32_t parseFrequencyMHzToHz(String input, bool &ok) {
  input.trim();
  input.replace(",", ".");
  if (input.length() == 0) {
    ok = false;
    return 0;
  }
  double mhz = input.toDouble();
  if (mhz < MIN_FREQ_MHZ || mhz > MAX_FREQ_MHZ) {
    ok = false;
    return 0;
  }
  ok = true;
  return (uint32_t)(mhz * 1000000.0 + 0.5);
}

void loadConfig() {
  prefs.begin("cw_rx_cfg", true);
  RF_FREQUENCY = prefs.getUInt("rf_hz", DEFAULT_RF_FREQUENCY);
  prefs.end();
  uint32_t minHz = (uint32_t)(MIN_FREQ_MHZ * 1e6);
  uint32_t maxHz = (uint32_t)(MAX_FREQ_MHZ * 1e6);
  if (RF_FREQUENCY < minHz || RF_FREQUENCY > maxHz) {
    RF_FREQUENCY = DEFAULT_RF_FREQUENCY;
  }
}

void saveConfig(uint32_t rfHz) {
  prefs.begin("cw_rx_cfg", false);
  prefs.putUInt("rf_hz", rfHz);
  prefs.end();
  RF_FREQUENCY = rfHz;
}

String htmlEscape(const String &s) {
  String out;
  out.reserve(s.length());
  for (size_t i = 0; i < s.length(); i++) {
    char c = s[i];
    if (c == '&') out += "&amp;";
    else if (c == '<') out += "&lt;";
    else if (c == '>') out += "&gt;";
    else if (c == '"') out += "&quot;";
    else out += c;
  }
  return out;
}

String configJson() {
  String json = "{\n";
  json += "  \"device\": \"M9WHQ Fox Hunt CW Receiver With Audio (868 MHz)\",\n";
  json += "  \"rf_frequency_hz\": " + String(RF_FREQUENCY) + ",\n";
  json += "  \"rf_frequency_mhz\": \"" + formatFrequencyMHz(RF_FREQUENCY) + "\"\n";
  json += "}\n";
  return json;
}

bool extractJsonNumber(const String &json, const String &key, uint32_t &value) {
  int keyPos = json.indexOf("\"" + key + "\"");
  if (keyPos < 0) return false;
  int colon = json.indexOf(':', keyPos);
  if (colon < 0) return false;
  int start = colon + 1;
  while (start < (int)json.length() && isspace((unsigned char)json[start])) start++;
  int end = start;
  while (end < (int)json.length() && (isdigit((unsigned char)json[end]) || json[end] == '.')) end++;
  if (end <= start) return false;
  String num = json.substring(start, end);
  value = (uint32_t)strtoul(num.c_str(), nullptr, 10);
  return true;
}

bool extractJsonString(const String &json, const String &key, String &value) {
  int keyPos = json.indexOf("\"" + key + "\"");
  if (keyPos < 0) return false;
  int colon = json.indexOf(':', keyPos);
  if (colon < 0) return false;
  int firstQuote = json.indexOf('"', colon + 1);
  if (firstQuote < 0) return false;
  int secondQuote = json.indexOf('"', firstQuote + 1);
  if (secondQuote < 0) return false;
  value = json.substring(firstQuote + 1, secondQuote);
  return true;
}

String pageHtml(const String &message = "") {
  String freq = formatFrequencyMHz(RF_FREQUENCY);
  String html = "<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'>";
  html += "<title>M9WHQ CW Receiver Config (868MHz)</title>";
  html += "<style>body{font-family:Arial,Helvetica,sans-serif;background:#111;color:#eee;margin:0;padding:20px;}";
  html += ".card{max-width:520px;margin:0 auto;background:#1d1d1d;border:1px solid #333;border-radius:10px;padding:18px;}";
  html += "h1{font-size:22px;margin:0 0 12px;}label{display:block;margin:14px 0 6px;}";
  html += "input[type=text],input[type=file]{width:100%;box-sizing:border-box;padding:10px;border-radius:6px;border:1px solid #555;background:#080808;color:#eee;}";
  html += "button,.btn{display:inline-block;margin-top:14px;padding:10px 14px;border:0;border-radius:6px;background:#2d7dd2;color:white;text-decoration:none;font-size:15px;cursor:pointer;}";
  html += ".btn2{background:#555}.msg{background:#143d1f;border:1px solid #2f8f46;padding:10px;border-radius:6px;margin:12px 0;}";
  html += ".small{color:#bbb;font-size:13px;line-height:1.4}.danger{background:#7a2424}.row{margin-top:18px;border-top:1px solid #333;padding-top:14px;}";
  html += "</style></head><body><div class='card'>";
  html += "<h1>M9WHQ Fox Hunt CW Receiver</h1>";
  html += "<div class='small'>Web Configuration Mode (863-870 MHz)</div>";
  if (message.length()) {
    html += "<div class='msg'>" + htmlEscape(message) + "</div>";
  }
  html += "<form method='POST' action='/save'>";
  html += "<label>Receive Frequency (MHz)</label>";
  html += "<input type='text' name='freq' value='" + htmlEscape(freq) + "' inputmode='decimal'>";
  html += "<div class='small'>Current stored frequency: " + htmlEscape(freq) + " MHz</div>";
  html += "<button type='submit'>Save and Reboot</button>";
  html += "</form>";
  html += "<div class='row'>";
  html += "<a class='btn btn2' href='/backup'>Download JSON Backup</a>";
  html += "</div>";
  html += "<div class='row'>";
  html += "<form method='POST' action='/restore' enctype='multipart/form-data'>";
  html += "<label>Restore Configuration JSON</label>";
  html += "<input type='file' name='file' accept='.json,application/json'>";
  html += "<button class='danger' type='submit'>Restore and Reboot</button>";
  html += "</form>";
  html += "</div>";
  html += "<div class='row small'>After saving or restoring, the receiver will reboot and return to normal receive mode.</div>";
  html += "</div></body></html>";
  return html;
}

void rebootSoon() {
  server.send(200, "text/html", pageHtml("Configuration saved. Rebooting now..."));
  display.clear();
  display.setTextAlignment(TEXT_ALIGN_CENTER);
  display.setFont(ArialMT_Plain_10);
  display.drawString(64, 24, "Config saved");
  display.drawString(64, 38, "Rebooting...");
  display.display();
  delay(2000);
  ESP.restart();
}

void handleRoot() {
  server.send(200, "text/html", pageHtml());
}

void handleSave() {
  bool ok = false;
  uint32_t hz = parseFrequencyMHzToHz(server.arg("freq"), ok);
  if (!ok) {
    server.send(400, "text/html", pageHtml("Invalid frequency. Please enter a frequency between 863.000 and 870.000 MHz."));
    return;
  }
  saveConfig(hz);
  rebootSoon();
}

void handleBackup() {
  server.sendHeader("Content-Disposition", "attachment; filename=foxhunt_rx_config.json");
  server.send(200, "application/json", configJson());
}

void handleRestore() {
  String json = "";
  if (server.hasArg("plain")) {
    json = server.arg("plain");
  } else {
    json = restoreUploadJson;
  }
  if (json.length() == 0) {
    server.send(400, "text/html", pageHtml("No JSON data received."));
    return;
  }
  uint32_t hz = 0;
  bool valid = false;
  if (extractJsonNumber(json, "rf_frequency_hz", hz)) {
    uint32_t minHz = (uint32_t)(MIN_FREQ_MHZ * 1e6);
    uint32_t maxHz = (uint32_t)(MAX_FREQ_MHZ * 1e6);
    if (hz >= minHz && hz <= maxHz) valid = true;
  }
  if (!valid) {
    String mhzString;
    if (extractJsonString(json, "rf_frequency_mhz", mhzString)) {
      bool ok = false;
      hz = parseFrequencyMHzToHz(mhzString, ok);
      valid = ok;
    }
  }
  if (!valid) {
    server.send(400, "text/html", pageHtml("Restore failed. JSON must contain rf_frequency_hz or rf_frequency_mhz with a valid 863-870 MHz frequency."));
    return;
  }
  saveConfig(hz);
  rebootSoon();
}

void handleRestoreUpload() {
  HTTPUpload& upload = server.upload();
  if (upload.status == UPLOAD_FILE_START) {
    restoreUploadJson = "";
  } else if (upload.status == UPLOAD_FILE_WRITE) {
    for (size_t i = 0; i < upload.currentSize; i++) {
      restoreUploadJson += (char)upload.buf[i];
    }
  }
}

void startConfigMode() {
  configMode = true;
  isConfigModeActive = true;
  ledcWriteTone(AUDIO_PIN, 0);
  WiFi.mode(WIFI_AP);
  WiFi.softAP(AP_SSID, AP_PASS);
  IPAddress ip = WiFi.softAPIP();
  display.clear();
  display.setFont(ArialMT_Plain_10);
  display.setTextAlignment(TEXT_ALIGN_LEFT);
  display.drawString(0, 0, "Config Mode");
  display.drawString(0, 12, AP_SSID);
  display.drawString(0, 24, "Pass: foxhunt70");
  display.drawString(0, 36, "IP: " + ip.toString());
  display.display();
  server.on("/", HTTP_GET, handleRoot);
  server.on("/save", HTTP_POST, handleSave);
  server.on("/backup", HTTP_GET, handleBackup);
  server.on("/restore", HTTP_POST, handleRestore, handleRestoreUpload);
  server.begin();
  while (true) {
    server.handleClient();
    delay(1);
  }
}

void initRadio() {
  // Placeholder for LoRa initialization logic
}

void checkRSSIAndPlayTone() {
  // Placeholder for main receive logic
}

void setup() {
  Serial.begin(115200);
  ArduinoOTA.onStart([]() {
    Serial.println("OTA Update Started");
    display.clear();
    display.setTextAlignment(TEXT_ALIGN_CENTER);
    display.drawString(64, 32, "Updating...");
    display.display();
  });
  ArduinoOTA.onEnd([]() { Serial.println("OTA Update Finished"); });
  ArduinoOTA.begin();
  pinMode(Vext, OUTPUT);
  digitalWrite(Vext, LOW);
  display.init();
  display.clear();
  display.setFont(ArialMT_Plain_10);
  display.drawString(0, 0, "Starting...");
  display.display();
  pinMode(PRG_BUTTON, INPUT_PULLUP);
  delay(2000);
  if (digitalRead(PRG_BUTTON) == LOW) {
    Serial.println("Button pressed at boot -> Entering Config Mode");
    startConfigMode();
    return;
  }
  Serial.println("Normal Mode");
  loadConfig();
  initRadio();
}

void loop() {
  if (!isConfigModeActive) {
    ArduinoOTA.handle();
    checkRSSIAndPlayTone();
  }
}
